#!/bin/bash
# Parameter and policy recovery: fit every policy to data generated by every policy (targets from
# analysis/make_recovery_targets.R). Writes results/recovery/fit_gen-<gen>_by-<fit>_stage{1,2}.csv.
set -eo pipefail
cd "$(dirname "$0")/.."
for gen in simultaneous sequential commit; do
  for fit in simultaneous sequential commit; do
    s1=results/recovery/fit_gen-${gen}_by-${fit}_stage1.csv
    [ -f "$s1" ] || julia -p 8 simulations/fit_grid.jl --policy $fit --n 200 --seed 3 --target results/recovery/targets_${gen}.csv --out $s1 > logs/recovery_${gen}_${fit}_1.log 2>&1
    julia -p 8 simulations/fit_grid.jl --policy $fit --n 150 --seed 4 --refine $s1 --target results/recovery/targets_${gen}.csv --out results/recovery/fit_gen-${gen}_by-${fit}_stage2.csv > logs/recovery_${gen}_${fit}_2.log 2>&1
    echo "gen=$gen fit=$fit done: $(date)"
  done
done
echo RECOVERY_DONE
